package com.nexusdrive.storage.service;import static org.junit.jupiter.api.Assertions.*;import com.nexusdrive.storage.config.StorageProperties;import java.nio.file.Path;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;class ChunkStorageServiceTest{@TempDir Path dir;@Test void putGetDelete()throws Exception{var p=new StorageProperties();p.setPath(dir);var s=new ChunkStorageService(p);s.init();s.put("safe-id",new byte[]{1,2});assertArrayEquals(new byte[]{1,2},s.get("safe-id"));s.delete("safe-id");assertThrows(RuntimeException.class,()->s.get("safe-id"));}@Test void rejectsTraversal(){var p=new StorageProperties();p.setPath(dir);var s=new ChunkStorageService(p);assertThrows(IllegalArgumentException.class,()->s.put("../bad",new byte[0]));}}
